(*----- Function qcpsat_fill_ints -----*)

Definition qcpsat_fill_ints_safety_wit_1 := 
forall (value_pre: Z) (n_pre: Z) (a_pre: Z) (PreH1 : (0 <= n_pre)) (PreH2 : (n_pre < INT_MAX)) ,
  ((( &( "i" ) )) # Int  |->_)
  **  ((( &( "a" ) )) # Ptr  |-> a_pre)
  **  ((( &( "n" ) )) # Int  |-> n_pre)
  **  ((( &( "value" ) )) # Int  |-> value_pre)
  **  (IntArray.undef_full a_pre n_pre )
|--
  “ (0 <= INT_MAX) ” 
  &&  “ ((INT_MIN) <= 0) ”
.

Definition qcpsat_fill_ints_safety_wit_2 := 
forall (value_pre: Z) (n_pre: Z) (a_pre: Z) (i: Z) (PreH1 : (i < n_pre)) (PreH2 : (0 <= i)) (PreH3 : (i <= n_pre)) (PreH4 : (0 <= n_pre)) (PreH5 : (n_pre < INT_MAX)) ,
  (IntArray.full a_pre (i + 1 ) (app ((repeat_Z (value_pre) (i))) ((cons (value_pre) ((@nil Z))))) )
  **  (IntArray.undef_seg a_pre (i + 1 ) n_pre )
  **  ((( &( "i" ) )) # Int  |-> i)
  **  ((( &( "a" ) )) # Ptr  |-> a_pre)
  **  ((( &( "value" ) )) # Int  |-> value_pre)
  **  ((( &( "n" ) )) # Int  |-> n_pre)
|--
  “ ((i + 1 ) <= INT_MAX) ” 
  &&  “ ((INT_MIN) <= (i + 1 )) ”
.

Definition qcpsat_fill_ints_entail_wit_1 := 
(
forall (value_pre: Z) (n_pre: Z) (a_pre: Z) (PreH1 : (0 <= n_pre)) (PreH2 : (n_pre < INT_MAX)) ,
  (IntArray.undef_full a_pre n_pre )
|--
  “ (0 <= 0) ” 
  &&  “ (0 <= n_pre) ” 
  &&  “ (0 <= n_pre) ” 
  &&  “ (n_pre < INT_MAX) ”
  &&  (IntArray.full a_pre 0 (repeat_Z (value_pre) (0)) )
  **  (IntArray.undef_seg a_pre 0 n_pre )
) \/
(
forall (value_pre: Z) (n_pre: Z) (PreH1 : (0 <= n_pre)) (PreH2 : (n_pre < INT_MAX)) ,
  TT && emp 
|--
  “ ((repeat_Z (value_pre) (0)) = (@nil Z)) ”
  &&  emp
).

Definition qcpsat_fill_ints_entail_wit_1_split_goal_1 := 
forall (value_pre: Z) (n_pre: Z) (PreH1 : (0 <= n_pre)) (PreH2 : (n_pre < INT_MAX)) ,
  ((repeat_Z (value_pre) (0)) = (@nil Z))
.

Definition qcpsat_fill_ints_entail_wit_2 := 
(
forall (value_pre: Z) (n_pre: Z) (a_pre: Z) (i: Z) (PreH1 : (i < n_pre)) (PreH2 : (0 <= i)) (PreH3 : (i <= n_pre)) (PreH4 : (0 <= n_pre)) (PreH5 : (n_pre < INT_MAX)) ,
  (IntArray.full a_pre (i + 1 ) (app ((repeat_Z (value_pre) (i))) ((cons (value_pre) ((@nil Z))))) )
  **  (IntArray.undef_seg a_pre (i + 1 ) n_pre )
|--
  “ (0 <= (i + 1 )) ” 
  &&  “ ((i + 1 ) <= n_pre) ” 
  &&  “ (0 <= n_pre) ” 
  &&  “ (n_pre < INT_MAX) ”
  &&  (IntArray.full a_pre (i + 1 ) (repeat_Z (value_pre) ((i + 1 ))) )
  **  (IntArray.undef_seg a_pre (i + 1 ) n_pre )
) \/
(
forall (value_pre: Z) (n_pre: Z) (i: Z) (PreH1 : (i < n_pre)) (PreH2 : (0 <= i)) (PreH3 : (i <= n_pre)) (PreH4 : (0 <= n_pre)) (PreH5 : (n_pre < INT_MAX)) ,
  TT && emp 
|--
  “ ((app ((repeat_Z (value_pre) (i))) ((cons (value_pre) ((@nil Z))))) = (repeat_Z (value_pre) ((i + 1 )))) ”
  &&  emp
).

