  (IntArray.undef_full retval n )
  **  ((( &( "res" ) )) # Ptr  |-> retval)
  **  ((( &( "wi" ) )) # Ptr  |-> wi_pre)
  **  ((( &( "wj" ) )) # Ptr  |-> wj_pre)
  **  ((( &( "s" ) )) # Ptr  |-> s_pre)
  **  ((&((s_pre)  # "sat_data" ->ₛ "v_size")) # Int  |-> n)
  **  (IntArray.full wi_pre n left )
  **  (IntArray.full wj_pre n right )
|--
  “ (0 <= INT_MAX) ” 
  &&  “ ((INT_MIN) <= 0) ”
.

